import React, { HTMLAttributes } from 'react';

import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import InfoCircleFill from '@pohodnik/icons/svg/Signs/InfoCircleFill';
import JustifyLeft from '@pohodnik/icons/svg/Typography/JustifyLeft';
import Link45Deg from '@pohodnik/icons/svg/UI/Link45Deg';
import clsx from 'clsx';

import { showArticleInModal } from '@apps/Articles/components/ArticleShowModal';
import foodActModal from '@apps/Hiking/@components/FoodActModal';
import { IHikingScheduleItem, IHikingTimezone } from '@apps/Hiking/@types/hiking.baseTypes';
import routePartModal from '@apps/Routes/RoutePartModal/routePartModal';
import { formattedLocaleTime } from '@helpers/dateHelper';
import { formatAltitude, formatDistance, formatFinance } from '@helpers/formatHelper';
import { getLocalDateByTimezone } from '@helpers/timezoneHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import { showModal } from '@ui-kit/Modal';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import style from './style.module.less';

interface IScheduleItemProps extends HTMLAttributes<HTMLDivElement> {
  id_hiking?: number;
  scheduleItem: IHikingScheduleItem;
  timezoneForStart?: IHikingTimezone;
  timezoneForFinish?: IHikingTimezone;
  toolbar?: React.ReactNode;
}

const ScheduleItem: React.FC<IScheduleItemProps> = ({
  scheduleItem,
  id_hiking,
  timezoneForFinish,
  timezoneForStart,
  children,
  toolbar,
  className,
  ...rest
}) => {
  const handleFoodClick = async (e: React.MouseEvent) => {
    e.preventDefault();

    if (!scheduleItem.foodAct || !id_hiking) {
      return;
    }
    if (scheduleItem.is_self_sufficiency) {
      return await confirmModal2(
        <div className="text-center" style={{ maxWidth: 400 }}>
          <h1> {scheduleItem.foodAct.name.toUpperCase()}</h1>
          <strong className="text-danger">Необходимо подготовить каждому самостоятельно!</strong>
          <p>
            В походе будет время (
            {scheduleItem.start.toLocaleString(undefined, {
              dateStyle: 'short',
              timeStyle: 'short',
            })}{' '}
            - {scheduleItem.finish.toLocaleTimeString(undefined, { timeStyle: 'short' })}) для того,
            чтобы при необходимости приготовить (или разогреть) и съесть его
          </p>
          <p>
            Рекомендуемая калорийность:{' '}
            <span className="text-warning">
              не менее {scheduleItem.foodAct.kkalCurrent ?? scheduleItem.foodAct.kkalTarget}
              &thinsp;ккал
            </span>
          </p>
          {!!scheduleItem.description?.length && (
            <p>
              <em>{scheduleItem.description}</em>
            </p>
          )}
        </div>,
      );
    }

    foodActModal({
      title: `На ${scheduleItem.foodAct.name.toLowerCase()}\u00a0${scheduleItem.start.toLocaleDateString()} (~${formattedLocaleTime(scheduleItem.start)})`,
      id_act: scheduleItem.foodAct.id,
      id_hiking: id_hiking,
      date: scheduleItem.start.toISOString().substr(0, 10),
    });
    e.preventDefault();
  };

  const handleRouteClick = (e: React.MouseEvent) => {
    scheduleItem.routeObject?.id &&
      routePartModal({ id_route_object: scheduleItem.routeObject?.id });
    e.preventDefault();
  };

  const getGmtShift = (timezone: string) => {
    return new Date()
      .toLocaleTimeString(navigator.language, {
        timeZone: timezone,
        timeZoneName: 'short',
      })
      .split(' ')
      .pop();
  };

  const getTooltipForDateAndTimezone = (date: Date, timezone?: IHikingTimezone) => {
    const rows: string[] = [];

    if (timezone) {
      rows.push(
        `${date.toLocaleString()} — Местное время для ${timezone.timezone} (${getGmtShift(timezone.timezone) ?? ''})`,
      );
      rows.push(
        `В ${Intl.DateTimeFormat().resolvedOptions().timeZone} в это время ${getLocalDateByTimezone(date, timezone.timezone).toLocaleString()}`,
      );
    } else {
      rows.push(date.toLocaleString());
    }

    return rows.join('\r\n');
  };

  return (
    <div
      key={scheduleItem.id}
      className={clsx(style.scheduleListItem, 'border-top', className)}
      {...rest}
    >
      <div className={style.scheduleTime}>
        <span
          className={clsx('border-bottom', timezoneForStart && 'text-dark')}
          data-timezone={
            timezoneForStart && getGmtShift(timezoneForStart.timezone)?.replace('GMT', '')
          }
          title={getTooltipForDateAndTimezone(scheduleItem.start, timezoneForStart)}
        >
          {formattedLocaleTime(scheduleItem.start)}
        </span>
        <span
          className={clsx(timezoneForFinish && 'text-dark')}
          data-timezone={
            timezoneForFinish && getGmtShift(timezoneForFinish.timezone)?.replace('GMT', '')
          }
          title={getTooltipForDateAndTimezone(scheduleItem.finish, timezoneForFinish)}
        >
          {formattedLocaleTime(scheduleItem.finish)}
        </span>
      </div>
      <div className={style.scheduleName}>
        <div style={{ lineHeight: 0.9 }}>
          {scheduleItem.name}
          {scheduleItem.is_self_sufficiency && (
            <>
              <br />
              <small>
                <small className="text-warning">Самообеспечение</small>
              </small>
            </>
          )}
        </div>

        <span className={clsx(style.scheduleNameExt)}>
          {scheduleItem.description && (
            <PohButton
              title={scheduleItem.description}
              size={ButtonSize.Small}
              icon
              onClick={() => showModal({ children: scheduleItem.description })}
            >
              <InfoCircleFill className="text-muted" />
            </PohButton>
          )}
          {scheduleItem.link && (
            <PohButton
              title={'Перейти по ссылке (откроется в новом окне)'}
              size={ButtonSize.Small}
              variant={ButtonVariant.Link}
              icon
              href={scheduleItem.link}
              target={'_blank'}
            >
              <Link45Deg />
            </PohButton>
          )}
          {scheduleItem.article && (
            <PohButton
              title={`Статья "${scheduleItem.article.name}"\n(откроется в модальном окне)`}
              size={ButtonSize.Small}
              variant={ButtonVariant.Link}
              icon
              onClick={() => scheduleItem.article && showArticleInModal(scheduleItem.article.id)}
            >
              <JustifyLeft />
            </PohButton>
          )}
        </span>
      </div>

      <div className={style.scheduleToolbar}>
        {scheduleItem.routeObject && (
          <>
            <PohBadge variant={BadgeVariant.Light}>
              {scheduleItem.routeObject.coordinates ? (
                <span
                  title={`${formatAltitude(scheduleItem.routeObject.coordinates[2] ?? 0)}.н.у.м`}
                >
                  <GeoAlt />
                </span>
              ) : (
                formatDistance(scheduleItem.routeObject.distance ?? 0).toString()
              )}
            </PohBadge>
            <a
              href="#where"
              className={clsx(style.scheduleLink, 'me-1')}
              onClick={handleRouteClick}
            >
              {scheduleItem.routeObject.coordinates ? 'Где это?' : 'подробнее'}
            </a>
          </>
        )}
        {scheduleItem.foodAct && (
          <>
            <PohBadge variant={BadgeVariant.Light}>
              {`${scheduleItem.foodAct?.kkalCurrent || scheduleItem.foodAct?.kkalTarget}\u2009ккал`}
            </PohBadge>
            <a
              href="#whatToEat"
              className={clsx(style.scheduleLink, 'me-1')}
              onClick={handleFoodClick}
            >
              Что на {scheduleItem.foodAct.name.toLowerCase()}?
            </a>
          </>
        )}
      </div>
      {scheduleItem.cost && (
        <small title="Примерная стоимость (с человека)">~{formatFinance(scheduleItem.cost)}</small>
      )}
      {children}
      {toolbar && <aside className="ms-2">{toolbar}</aside>}
    </div>
  );
};

export default ScheduleItem;
