import React from 'react';

import { getRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import { IRouteObject, RouteObjectType } from '@apps/Routes/@types/routes.types';
import PageLoader from '@components/PageLoader';
import PolylineInfo from '@components/PolylineInfo';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';

const RoutePartsModal: React.FC<{ route_object_ids: number[]; id_route: number }> = ({
  route_object_ids,
  id_route,
}) => {
  const [loading, setLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IRouteObject[]>([]);
  React.useEffect(() => {
    const start = async () => {
      try {
        const res = await getRouteObjectsAsync(id_route);
        const filtered = res.filter((x) => route_object_ids.includes(x.id));

        setData(filtered);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setLoading(false);
      }
    };

    start();
  }, []);

  if (loading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!data.length) {
    return <Empty>Пока не понятно :(</Empty>;
  }

  const lines = data.filter((x) => x.type === RouteObjectType.Line);
  const allPoints: Array<[number, number, number]> = lines.reduce<[number, number, number][]>(
    (acc, val) => {
      const newPoints = val.points as unknown as Array<[number, number, number]>;
      return [...acc, ...newPoints];
    },
    [],
  );

  return (
    <div style={{ width: '80dvw' }}>
      <PolylineInfo
        points={allPoints}
        poi={data.filter((x) => x.type === RouteObjectType.Point)}
        name={lines.map((l) => l.name).join(', ')}
        height={320}
      />
    </div>
  );
};

export default RoutePartsModal;
