import React from 'react';

import { getRouteObjectAsync } from '@apps/Routes/@services/routes.service';
import { IRouteObject, RouteObjectType } from '@apps/Routes/@types/routes.types';
import MapPoint from '@components/MapPoint';
import PageLoader from '@components/PageLoader';
import PolylineInfo from '@components/PolylineInfo';
import Empty from '@ui-kit/Empty';

const RoutePartModal: React.FC<{ id_route_object: number }> = ({ id_route_object }) => {
  const [data, setData] = React.useState<IRouteObject | null>(null);
  React.useEffect(() => {
    getRouteObjectAsync(id_route_object).then(setData);
  }, []);

  if (data == null) {
    return <PageLoader />;
  }

  if (!id_route_object) {
    return <Empty>Пока не понятно :(</Empty>;
  }

  if (data.type === RouteObjectType.Line) {
    return (
      <div style={{ width: '80dvw' }}>
        <PolylineInfo points={data.points} name={data.name} height={320} />
      </div>
    );
  } else {
    return <MapPoint point={data.coordinates as [number, number]} height={400} />;
  }
};

export default RoutePartModal;
